// Window
// ======

// All window effects share this source; each entry is present only when
// its effect is reachable.

#ifdef __OBJC__

#import <AppKit/AppKit.h>
#import <QuartzCore/QuartzCore.h>

#elif defined(__linux__)

// The X11 window: its own connection (so its queue holds only its
// events), the frame's image, the events pumped since the last frame,
// five words each (cid, a, b, c, d) as on the Mac, and whether it
// holds the pointer.
#include <X11/Xlib.h>
#include <X11/Xutil.h>
#include <X11/keysym.h>

typedef struct {
  Display* dpy;
  Window   win;
  Atom     del;
  XImage*  img;
  u32      n;
  u32      cap;
  u32*     evs;
  u32      grab;
} BendWin;

#endif

#ifdef CID(Window.export_ref)

Term window_export_ref_run(Env e, Term* f, IoWork* w) {
#if defined(__linux__) && !defined(__OBJC__)
  BendWin* win = (BendWin*)(intptr_t)io_hand_v(f[0]);
  const char* display = DisplayString(win->dpy);
  if (display == NULL || display[0] == 0 || win->win == 0) {
    return io_tup(e, f[0], io_fail(e, EIO,
      "Window.export_ref: missing X11 display or window"));
  }
  if (win->win > UINT32_MAX) {
    return io_tup(e, f[0], io_fail(e, EOVERFLOW,
      "Window.export_ref: X11 ID exceeds U32"));
  }
  // Publish prior requests to other connections without discarding events.
  XSync(win->dpy, False);
  Term ref = io_node(e, CID(X11WindowRef),
    io_str(e, display, strlen(display)), (u32)win->win);
  return io_tup(e, f[0], io_done(e, ref));
#else
  return io_tup(e, f[0], io_fail(e, ENOTSUP,
    "Window.export_ref: external reference is unavailable on this backend"));
#endif
}

static void __attribute__((constructor)) window_export_ref_use(void) {
  io_eff(CID(Window.export_ref), window_export_ref_run, 0);
}

#endif

#ifdef CID(Window.capture)

#if defined(__linux__) && !defined(__OBJC__)

typedef struct {
  Display* dpy;
  unsigned long first;
  int (*previous)(Display*, XErrorEvent*);
  int error;
} WindowCaptureTrap;
// File
// ====

static void file_read_call(IoWork* w) {
  int fd = (int)w->hand;
  w->size = io_sys_end(w, read(fd, w->data, w->word));
}

static Term file_read_start(Term file, u64 max, IoWork* w,
  IoCall call, IoPack pack) {
  w->hand = (intptr_t)io_hand_v(file);
  w->word = max < INT32_MAX ? max : INT32_MAX;
  w->data = io_mem(malloc(w->word + 1));
  return io_work(w, call, pack);
}

#ifdef CID(File.read)

static Term file_read_pack(Env e, IoWork* w) {
  Term r = io_res(e, w, io_str(e, w->data, w->size));
  free(w->data);
  return io_tup(e, io_hand(w->hand), r);
}

